'use strict';

const fs = require('fs/promises');
const path = require('path');

const STATUS_URL = 'http://127.0.0.1:58843/status';
const OUTPUT_DIR = path.join(__dirname, 'results');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'status.json');

async function main() {
  const response = await fetch(STATUS_URL);

  if (!response.ok) {
    throw new Error(`GET ${STATUS_URL} failed with HTTP ${response.status}`);
  }

  const payload = await response.json();

  if (payload.status !== 200) {
    throw new Error(`Unexpected status from ${STATUS_URL}: ${JSON.stringify(payload.status)}`);
  }

  await fs.mkdir(OUTPUT_DIR, { recursive: true });
  await fs.writeFile(OUTPUT_FILE, `${JSON.stringify({ status: payload.status }, null, 2)}\n`, 'utf8');

  console.log(`Wrote status=${payload.status} to ${OUTPUT_FILE}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exitCode = 1;
});

